<div id="analisis-comercial" class="mt-6 rounded-xl bg-white shadow-sm ring-1 ring-gray-950/5 dark:bg-gray-900 dark:ring-white/10">
    <div class="border-b border-gray-200 px-6 py-4 dark:border-white/10"><h3 class="font-semibold">Análisis comercial mensual</h3><p class="text-sm text-gray-500">Información consultada de forma independiente.</p></div>
    <div class="flex flex-wrap gap-2 px-6 py-4"><button data-tipo="vendidos">Más vendidos</button><button data-tipo="rentables">Más rentables</button><button data-tipo="clientes">Clientes</button><button data-tipo="resumen">Resumen</button><input type="month" value="{{ now()->format('Y-m') }}"></div>
    <div class="overflow-x-auto px-6 pb-5"><table class="w-full text-sm"><thead></thead><tbody><tr><td class="py-4 text-gray-500">Cargando análisis…</td></tr></tbody></table></div>
</div>
<script>
(() => { const root=document.getElementById('analisis-comercial'); if(!root)return; const head=root.querySelector('thead'),body=root.querySelector('tbody'),month=root.querySelector('input'); let type='vendidos'; const load=async()=>{body.innerHTML='<tr><td class="py-4 text-gray-500">Cargando análisis…</td></tr>'; try { const r=await fetch(`{{ route('analisis-comercial.datos') }}?tipo=${type}&periodo=${month.value}`,{headers:{Accept:'application/json'}}); if(!r.ok)throw new Error(); const d=await r.json(); head.innerHTML='<tr>'+d.columnas.map(x=>`<th class="border-y px-3 py-2 text-left">${x}</th>`).join('')+'</tr>'; body.innerHTML=d.filas.length?d.filas.map(row=>'<tr>'+row.map(x=>`<td class="border-b px-3 py-2">${x}</td>`).join('')+'</tr>').join(''):`<tr><td colspan="${d.columnas.length}" class="py-4 text-gray-500">No hay datos para este mes.</td></tr>`; } catch(e) { head.innerHTML=''; body.innerHTML='<tr><td class="py-4 text-gray-500">No se pudo cargar el análisis. El sistema continúa disponible.</td></tr>'; }}; root.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{type=b.dataset.tipo;load()})); month.addEventListener('change',load); load(); })();
</script>
